{
  "predictors": [
    {
      "name": "Employee Productivity Ratio",
      "construction": "Total Revenue divided by Number of Employees, calculated annually from company financial statements.",
      "rationale": "Firms with higher employee productivity may have more efficient operations, leading to greater profitability and potentially higher stock returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Intensity",
      "construction": "Research and Development Expense divided by Total Sales, calculated annually.",
      "rationale": "Firms investing heavily in R&D may be developing innovative products and technologies that could lead to future growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Concentration Index",
      "construction": "Herfindahl Index based on the proportion of purchases from key suppliers as disclosed in company reports.",
      "rationale": "Lower supplier concentration might indicate better bargaining power and supply chain stability.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Merger Activity Indicator",
      "construction": "Binary indicator set to 1 if the firm has been involved in any merger or acquisition activity in the past year, 0 otherwise.",
      "rationale": "Firms engaging in merger activities may be actively seeking growth opportunities, possibly leading to enhanced future returns.",
      "higher_returns_for": "value of 1"
    },
    {
      "name": "Technology Adoption Index",
      "construction": "Score based on the number of new technology mentions in annual reports, adjusted for industry norms.",
      "rationale": "Firms that rapidly adopt technology may gain competitive advantages, potentially increasing their market share and returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CEO Equity Stake",
      "construction": "Percentage of total outstanding shares owned by the CEO, as reported in proxy statements.",
      "rationale": "Higher CEO equity stakes may align management interests with shareholders, potentially leading to better company performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Commitment Score",
      "construction": "Composite score based on the number of environmental policies and practices disclosed in company reports.",
      "rationale": "Firms with strong environmental commitments may reduce future regulatory risks and attract environmentally-conscious investors.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Foreign Sales Proportion",
      "construction": "Total foreign sales divided by total sales, calculated from geographic segment disclosures.",
      "rationale": "Firms with significant foreign sales might be better diversified and less susceptible to domestic economic downturns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Advertising Efficiency Ratio",
      "construction": "Total Sales divided by Advertising Expenses, calculated annually from financial statements.",
      "rationale": "Higher advertising efficiency indicates better return on marketing investments, potentially enhancing profitability and returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Activity Index",
      "construction": "Number of patents filed by the firm in the past year, adjusted for industry averages.",
      "rationale": "Active patent filing may signal innovative activity, positioning the firm for future growth and competitive advantage.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
